def biased_step(self, record, rng, restart=None):
    if restart is not None or record[0] != "A":
        return original_step(self, record, rng, restart)
    class FirstRestartOverride:
        def __init__(self):
            self.calls = 0
        def randrange(self, stop):
            ticket = rng.randrange(stop)
            first = self.calls == 0
            self.calls += 1
            return 0 if first else ticket
    return original_step(self, record, FirstRestartOverride())
